from("direct:orders")
    .dynamicRouter(method(RuleTableBean.class, "next"));

// bean: consult the reloadable rule base, return the next endpoint URI or null
public String next(String body, @ExchangeProperties Map<String, Object> props) {
    int hop = (int) props.getOrDefault("hop", 0);
    props.put("hop", hop + 1);          // state on the Exchange, not on the bean
    return ruleBase.lookup(body, hop);   // null ends routing - mandatory
}

